package com.tecsup;
import java.util.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/productos") public class ProductoController { private final ProductoRepository repo; private final CategoriaClient categorias; public ProductoController(ProductoRepository r,CategoriaClient c){repo=r;categorias=c;} private Producto enrich(Producto p){p.categoria=categorias.get(p.categoriaId);return p;} @GetMapping public List<Producto> all(){return repo.findAll().stream().map(this::enrich).toList();} @GetMapping("/{id}") public Producto one(@PathVariable Long id){return enrich(repo.findById(id).orElseThrow());} @PostMapping public Producto create(@Valid @RequestBody Producto p){p.id=null;return enrich(repo.save(p));} @PutMapping("/{id}") public Producto update(@PathVariable Long id,@Valid @RequestBody Producto p){p.id=id;return enrich(repo.save(p));} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
